						exists = owner
						any_neighbor_system = {
							exists = owner
						}
					}
					can_spawn_astral_rift_natural_generation = yes
				}

				weights = {

base = 1
modifier = {
	factor = 6
	is_star_class = sc_black_hole
}
modifier = {
	factor = 5
	is_star_class = sc_pulsar
}
modifier = {
	factor = 4
	is_star_class = sc_neutron_star
}
